function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof SIKH_INFO&&(n.innerHTML=SIKH_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderCoins(){const n=document.getElementById("coins-grid");n&&"undefined"!=typeof COIN_EXAMPLES&&(n.innerHTML=COIN_EXAMPLES.map(n=>`\n        <div class="coin-card">\n            <h3>🪙 ${n.name}</h3>\n            <span class="coin-mint-tag">Mint: ${n.mint} • ${n.era}</span>\n            <p><strong>Metal & Weight:</strong> ${n.metal}</p>\n            <p><strong>Obverse Couplet:</strong> <em>"${n.inscription}"</em></p>\n            <p><strong>Reverse Inscription:</strong> <em>"${n.reverseText}"</em></p>\n            <p><strong>Iconic Motif:</strong> ${n.motif}</p>\n            <p class="coin-sig"><strong>Historical Context:</strong> ${n.significance}</p>\n        </div>\n    `).join(""))}function renderInscriptions(){const n=document.getElementById("inscriptions-grid");n&&"undefined"!=typeof INSCRIPTION_BREAKDOWN&&(n.innerHTML=INSCRIPTION_BREAKDOWN.map(n=>`\n        <div class="inscription-card">\n            <h3>✨ ${n.phrase}</h3>\n            <span class="meaning-tag">Meaning: ${n.meaning}</span>\n            <p>${n.significance}</p>\n        </div>\n    `).join(""))}function renderMints(){const n=document.getElementById("mints-grid");n&&"undefined"!=typeof SIKH_MINTS&&(n.innerHTML=SIKH_MINTS.map(n=>`\n        <div class="mint-card">\n            <h3>🏛️ ${n.name}</h3>\n            <span class="mint-loc">Region: ${n.location}</span>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const n=document.getElementById("timeline-container");n&&"undefined"!=typeof TIMELINE_EVENTS&&(n.innerHTML=TIMELINE_EVENTS.map(n=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${n.year}</div>\n            <div class="timeline-content">\n                <h3>${n.title}</h3>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderCoins(),renderInscriptions(),renderMints(),renderTimeline(),renderReferences(),initThemeToggle()});